import{_ as e,a as d,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"List Products","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-products-list","title":"List Products (Datagrid)","description":"The canonical admin product listing — paginated, filterable, and sortable, mirroring the Bagisto admin Catalog → Products datagrid. Returns the full product row in the standard `{ data, meta }` envelope.","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/products?per_page=10&page=1&type=simple&status=1\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","variables":"per_page=10&page=1&type=simple&status=1\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 22,\\n      \\"sku\\": \\"bagistoNGRY3424234KJCKJK\\",\\n      \\"name\\": \\"Acme Drawstring Bag\\",\\n      \\"type\\": \\"simple\\",\\n      \\"status\\": 1,\\n      \\"price\\": \\"3000.0000\\",\\n      \\"formattedPrice\\": \\"$3,000.00\\",\\n      \\"specialPrice\\": \\"2700.0000\\",\\n      \\"formattedSpecialPrice\\": \\"$2,700.00\\",\\n      \\"specialPriceFrom\\": null,\\n      \\"specialPriceTo\\": null,\\n      \\"quantity\\": 98,\\n      \\"baseImageUrl\\": \\"http://localhost:8000/storage/product/22/1qfyoglc5BP46kofrxYrkJ2MXRxu9lAVG3BDFlTZ.webp\\",\\n      \\"imagesCount\\": 1,\\n      \\"categoryId\\": null,\\n      \\"categoryName\\": null,\\n      \\"channel\\": \\"default\\",\\n      \\"locale\\": \\"en\\",\\n      \\"attributeFamilyId\\": 1,\\n      \\"attributeFamilyName\\": \\"Default\\",\\n      \\"urlKey\\": \\"acme-drawstring-bag\\",\\n      \\"visibleIndividually\\": true,\\n      \\"shortDescription\\": \\"Many desktop publishing packages and web page editors now use\\",\\n      \\"description\\": \\"A roomy drawstring bag in durable cotton canvas.\\",\\n      \\"metaTitle\\": \\"\\",\\n      \\"metaDescription\\": \\"\\",\\n      \\"metaKeywords\\": \\"\\",\\n      \\"weight\\": 32,\\n      \\"featured\\": true,\\n      \\"new\\": true,\\n      \\"createdAt\\": \\"2024-04-19 11:56:43\\",\\n      \\"updatedAt\\": \\"2026-04-23 16:36:14\\"\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 27,\\n    \\"total\\": 265,\\n    \\"from\\": 1,\\n    \\"to\\": 10\\n  }\\n}\\n","commonErrors":[{"error":"Unauthorized (401)","cause":"Missing, invalid, expired, or revoked admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products.md","filePath":"api/rest-api/admin/catalog/products.md","lastUpdated":1787290888000}'),a={name:"api/rest-api/admin/catalog/products.md"};function c(i,t,n,s,l,u){return o(),d("div",null,t[0]||(t[0]=[r('<h1 id="list-products" tabindex="-1">List Products <a class="header-anchor" href="#list-products" aria-label="Permalink to &quot;List Products&quot;">​</a></h1><p>The <strong>canonical admin product listing</strong> — a paginated, filterable, and sortable product list that mirrors the Bagisto admin <strong>Catalog → Products</strong> datagrid 1:1. Same columns, same filters, and the same sort options used by the admin screen. This is the listing you want for product-management screens.</p><p>For the product types, the two-step create flow, <code>status</code> versus <code>visibleIndividually</code>, and the per-product sub-resources, see the <a href="/api/rest-api/admin/catalog/products/">Products overview</a>.</p><p>A separate slim search, <a href="/api/rest-api/admin/catalog/products/list.html"><code>GET /api/admin/products</code></a>, powers the Create-Order &quot;Add Product&quot; modal only. It is not the listing.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Authentication</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/products</code></td><td>GET</td><td>Admin Bearer token</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>page</code></td><td>integer</td><td>Page number (1-based, default <code>1</code>)</td><td><code>1</code></td></tr><tr><td><code>per_page</code></td><td>integer</td><td>Items per page (default <code>10</code>, max <code>50</code>)</td><td><code>10</code></td></tr><tr><td><code>product_id</code></td><td>string</td><td>Filter by product ID — single integer or comma-separated list</td><td><code>142</code> or <code>1,2,3</code></td></tr><tr><td><code>sku</code></td><td>string</td><td>Partial SKU match (SQL <code>LIKE %value%</code>)</td><td><code>SP-001</code></td></tr><tr><td><code>name</code></td><td>string</td><td>Partial product name match (SQL <code>LIKE %value%</code>)</td><td><code>Classic Watch</code></td></tr><tr><td><code>type</code></td><td>string</td><td>Filter by product type</td><td><code>simple</code></td></tr><tr><td><code>status</code></td><td>integer</td><td>Filter by status: <code>0</code> = disabled, <code>1</code> = enabled</td><td><code>1</code></td></tr><tr><td><code>attribute_family</code></td><td>integer</td><td>Filter by attribute family ID</td><td><code>1</code></td></tr><tr><td><code>channel</code></td><td>string</td><td>Channel code for locale/price resolution (default: current channel)</td><td><code>default</code></td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code for name/category resolution (default: app locale)</td><td><code>en</code></td></tr><tr><td><code>price_from</code></td><td>number</td><td>Minimum price filter (inclusive)</td><td><code>10.00</code></td></tr><tr><td><code>price_to</code></td><td>number</td><td>Maximum price filter (inclusive)</td><td><code>500.00</code></td></tr><tr><td><code>price</code></td><td>string</td><td>Price range shorthand — <code>&quot;min,max&quot;</code>. Overridden by <code>price_from</code>/<code>price_to</code> when both are present</td><td><code>10,500</code></td></tr><tr><td><code>sort</code></td><td>string</td><td>Column to sort by (see Sorting section below)</td><td><code>product_id</code></td></tr><tr><td><code>order</code></td><td>string</td><td>Sort direction: <code>asc</code> or <code>desc</code> (default <code>desc</code>)</td><td><code>desc</code></td></tr></tbody></table><h3 id="valid-type-values" tabindex="-1">Valid <code>type</code> values <a class="header-anchor" href="#valid-type-values" aria-label="Permalink to &quot;Valid `type` values&quot;">​</a></h3><p><code>simple</code>, <code>configurable</code>, <code>bundle</code>, <code>grouped</code>, <code>downloadable</code>, <code>virtual</code>, <code>booking</code></p><h2 id="response-shape" tabindex="-1">Response Shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response Shape&quot;">​</a></h2><p>Responses use the standard admin <code>{ data, meta }</code> envelope.</p><h3 id="meta-object" tabindex="-1"><code>meta</code> object <a class="header-anchor" href="#meta-object" aria-label="Permalink to &quot;`meta` object&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>currentPage</code></td><td>integer</td><td>Current page number (1-based)</td></tr><tr><td><code>perPage</code></td><td>integer</td><td>Number of items on this page</td></tr><tr><td><code>lastPage</code></td><td>integer</td><td>Total number of pages</td></tr><tr><td><code>total</code></td><td>integer</td><td>Total matching products</td></tr><tr><td><code>from</code></td><td>integer</td><td>1-based index of the first item on this page</td></tr><tr><td><code>to</code></td><td>integer</td><td>1-based index of the last item on this page</td></tr></tbody></table><h3 id="row-fields-data" tabindex="-1">Row fields (<code>data[]</code>) <a class="header-anchor" href="#row-fields-data" aria-label="Permalink to &quot;Row fields (`data[]`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Product ID</td></tr><tr><td><code>sku</code></td><td>string|null</td><td>Product SKU</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Product name (resolved via <code>locale</code> and <code>channel</code>)</td></tr><tr><td><code>type</code></td><td>string|null</td><td>Product type (e.g. <code>simple</code>, <code>configurable</code>)</td></tr><tr><td><code>status</code></td><td>integer|null</td><td><code>1</code> = enabled, <code>0</code> = disabled</td></tr><tr><td><code>price</code></td><td>string|null</td><td>Raw price value (decimal string, e.g. <code>&quot;3000.0000&quot;</code>)</td></tr><tr><td><code>formattedPrice</code></td><td>string|null</td><td>Locale-formatted price (e.g. <code>&quot;$3,000.00&quot;</code>)</td></tr><tr><td><code>specialPrice</code></td><td>string|null</td><td>Raw special (sale) price as a decimal string; <code>null</code> if none</td></tr><tr><td><code>formattedSpecialPrice</code></td><td>string|null</td><td>Locale-formatted special price; <code>null</code> if none</td></tr><tr><td><code>specialPriceFrom</code></td><td>string|null</td><td>Start of the special-price window; <code>null</code> unless a dated window is set</td></tr><tr><td><code>specialPriceTo</code></td><td>string|null</td><td>End of the special-price window; <code>null</code> unless a dated window is set</td></tr><tr><td><code>quantity</code></td><td>integer</td><td>Sum of inventory qty across all inventory sources</td></tr><tr><td><code>baseImageUrl</code></td><td>string|null</td><td>Storage URL of the product&#39;s first image; <code>null</code> if no images</td></tr><tr><td><code>imagesCount</code></td><td>integer</td><td>Total number of images attached to the product</td></tr><tr><td><code>categoryId</code></td><td>integer|null</td><td>ID of the first category this product belongs to; <code>null</code> if uncategorized</td></tr><tr><td><code>categoryName</code></td><td>string|null</td><td>Translated name of that category (resolved via <code>locale</code>); <code>null</code> if uncategorized</td></tr><tr><td><code>channel</code></td><td>string|null</td><td>Channel code used for resolution</td></tr><tr><td><code>locale</code></td><td>string|null</td><td>Locale code used for resolution</td></tr><tr><td><code>attributeFamilyId</code></td><td>integer|null</td><td>Attribute family ID</td></tr><tr><td><code>attributeFamilyName</code></td><td>string|null</td><td>Attribute family name</td></tr><tr><td><code>urlKey</code></td><td>string|null</td><td>URL slug (e.g. <code>acme-drawstring-bag</code>)</td></tr><tr><td><code>visibleIndividually</code></td><td>boolean|null</td><td>Whether the product appears in category/search listings</td></tr><tr><td><code>shortDescription</code></td><td>string|null</td><td>Short description, HTML</td></tr><tr><td><code>description</code></td><td>string|null</td><td>Full description, HTML</td></tr><tr><td><code>metaTitle</code></td><td>string|null</td><td>SEO meta title (empty string when unset)</td></tr><tr><td><code>metaDescription</code></td><td>string|null</td><td>SEO meta description (empty string when unset)</td></tr><tr><td><code>metaKeywords</code></td><td>string|null</td><td>SEO meta keywords (empty string when unset)</td></tr><tr><td><code>weight</code></td><td>number|null</td><td>Product weight</td></tr><tr><td><code>featured</code></td><td>boolean</td><td>Whether the product is flagged as featured</td></tr><tr><td><code>new</code></td><td>boolean</td><td>Whether the product is flagged as &quot;new&quot;</td></tr><tr><td><code>createdAt</code></td><td>string</td><td>Creation timestamp</td></tr><tr><td><code>updatedAt</code></td><td>string</td><td>Last-update timestamp</td></tr></tbody></table><p>Four traps in these values:</p><ul><li><strong><code>price</code> and <code>specialPrice</code> are decimal strings</strong>, not numbers — <code>&quot;3000.0000&quot;</code>. Everything else numeric on the row (<code>quantity</code>, <code>imagesCount</code>, <code>weight</code>, <code>attributeFamilyId</code>) is a real number, so cast the two price fields before arithmetic or comparison.</li><li><strong><code>specialPriceFrom</code> and <code>specialPriceTo</code> stay <code>null</code> unless a dated window is set.</strong> A product can carry a <code>specialPrice</code> with both dates <code>null</code> — that means the sale price applies indefinitely, not that there is no sale.</li><li><strong><code>categoryId</code> and <code>categoryName</code> describe the first category only.</strong> A product in three categories reports one, matching what the datagrid shows. Read the full set from the <code>categories</code> block on <a href="/api/rest-api/admin/catalog/products/products-detail.html">Product Detail</a>.</li><li><strong><code>quantity</code> is a sum across inventory sources</strong>, not a per-source figure. For the breakdown use <a href="/api/rest-api/admin/catalog/products/inventories-list.html">List Inventories</a>.</li></ul><p>The same product over GraphQL comes back with <strong>different JSON types</strong> — <code>status</code>, <code>quantity</code>, <code>weight</code>, <code>featured</code>, and <code>new</code> are all strings there, and timestamps are ISO 8601 rather than the <code>2026-04-19 11:56:43</code> form used here. A parsing helper written against this endpoint will not survive being pointed at <code>adminCatalogProducts</code>.</p><h3 id="fields-that-stay-null-on-the-listing" tabindex="-1">Fields That Stay Null on the Listing <a class="header-anchor" href="#fields-that-stay-null-on-the-listing" aria-label="Permalink to &quot;Fields That Stay Null on the Listing&quot;">​</a></h3><p>Every row carries all 55 keys, but the following resolve only on the single-product endpoint <code>GET /api/admin/catalog/products/{id}</code>:</p><ul><li><code>taxCategoryId</code>, <code>manageStock</code>, <code>inStock</code>, <code>attributes</code>, <code>bookingProduct</code>, <code>warnings</code></li><li>the relation blocks: <code>translations</code>, <code>images</code>, <code>videos</code>, <code>categories</code>, <code>inventories</code>, <code>customerGroupPrices</code>, <code>superAttributes</code>, <code>variants</code>, <code>bundleOptions</code>, <code>linkedProducts</code>, <code>downloadableLinks</code>, <code>downloadableSamples</code>, <code>customizableOptions</code>, <code>channels</code>, <code>relatedProducts</code>, <code>upSells</code>, <code>crossSells</code></li></ul><p>They are present as <code>null</code> rather than omitted, so a key-existence check is not a substitute for a null check.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Two forms are accepted — choose whichever suits your client:</p><table tabindex="0"><thead><tr><th>Form</th><th>Example</th></tr></thead><tbody><tr><td>Compound <code>sort</code> param</td><td><code>?sort=name-asc</code></td></tr><tr><td>Separate <code>sort</code> + <code>order</code> params</td><td><code>?sort=name&amp;order=asc</code></td></tr></tbody></table><p>When both <code>order</code> and a compound <code>sort</code> value are present, the explicit <code>order</code> param takes precedence.</p><p><strong>Sortable columns:</strong></p><table tabindex="0"><thead><tr><th><code>sort</code> value</th><th>Sorts by</th></tr></thead><tbody><tr><td><code>product_id</code></td><td>Product ID (default)</td></tr><tr><td><code>name</code></td><td>Product name</td></tr><tr><td><code>sku</code></td><td>SKU</td></tr><tr><td><code>price</code></td><td>Price</td></tr><tr><td><code>quantity</code></td><td>Inventory quantity (SUM across sources)</td></tr><tr><td><code>status</code></td><td>Enabled/disabled status</td></tr><tr><td><code>type</code></td><td>Product type</td></tr><tr><td><code>attribute_family</code></td><td>Attribute family ID</td></tr><tr><td><code>channel</code></td><td>Channel code</td></tr></tbody></table><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><ul><li>Default page size: <strong>10</strong> items</li><li>Maximum page size: <strong>50</strong> items</li><li>Use <code>?page=N</code> for page navigation and <code>?per_page=N</code> to control page size</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP Status</th><th>Cause</th></tr></thead><tbody><tr><td><code>401</code></td><td>Missing, malformed, expired, or revoked admin Bearer token</td></tr></tbody></table><p>The listing never rejects a bad filter, but the three ways it can go wrong are not the same:</p><ul><li><strong>An unknown parameter is ignored.</strong> A misspelled <code>?tpye=simple</code> returns <code>200</code> and the unfiltered list — no error, no hint.</li><li><strong>An out-of-range <code>status</code> is dropped.</strong> <code>?status=7</code> returns the full unfiltered count, not zero.</li><li><strong>An unrecognised <code>type</code> is applied and matches nothing.</strong> <code>?type=notatype</code> returns <code>total: 0</code>. It does not behave like <code>status</code>, so an empty result may mean a typo rather than an empty catalog.</li></ul><p><code>?per_page=999</code> is clamped to <code>50</code> rather than rejected.</p><h2 id="search-engine" tabindex="-1">Search Engine <a class="header-anchor" href="#search-engine" aria-label="Permalink to &quot;Search Engine&quot;">​</a></h2><p>The listing always queries the database. Configuring the admin panel to use Elasticsearch for catalog search does not change this endpoint&#39;s behaviour.</p><h2 id="how-it-differs-from-the-storefront-listing" tabindex="-1">How It Differs From the Storefront Listing <a class="header-anchor" href="#how-it-differs-from-the-storefront-listing" aria-label="Permalink to &quot;How It Differs From the Storefront Listing&quot;">​</a></h2><ul><li><strong>No implicit <code>status = 1</code> filter.</strong> <code>GET /api/shop/products</code> hides disabled products; this endpoint returns every status so an admin can find a draft or disabled product. Pass <code>?status=1</code> for enabled only.</li><li><strong>Products with no inventory</strong> return <code>quantity: 0</code>, and products with no images return <code>baseImageUrl: null</code> with <code>imagesCount: 0</code> — neither is excluded from the listing.</li></ul>',40)]))}const g=e(a,[["render",c]]);export{h as __pageData,g as default};
